pub fn upcase_ascii(input: &[u8]) -> Vec<u8> {
    input.iter().map(|byte| byte.to_ascii_uppercase()).collect()
}

pub fn downcase_ascii(input: &[u8]) -> Vec<u8> {
    input.iter().map(|byte| byte.to_ascii_lowercase()).collect()
}

pub fn capitalize_ascii(input: &[u8]) -> Vec<u8> {
    let mut output = input.to_vec();
    if let Some((first, rest)) = output.split_first_mut() {
        *first = first.to_ascii_uppercase();
        for byte in rest {
            *byte = byte.to_ascii_lowercase();
        }
    }
    output
}

pub fn uppercase_first_ascii(input: &[u8]) -> Vec<u8> {
    let mut output = input.to_vec();
    if let Some(first) = output.first_mut() {
        *first = first.to_ascii_uppercase();
    }
    output
}

pub fn lowercase_first_ascii(input: &[u8]) -> Vec<u8> {
    let mut output = input.to_vec();
    if let Some(first) = output.first_mut() {
        *first = first.to_ascii_lowercase();
    }
    output
}

pub fn titleize_ascii_words(input: &[u8]) -> Vec<u8> {
    let mut output = Vec::with_capacity(input.len());
    let mut segment_start = 0;

    for index in 0..=input.len() {
        if index == input.len() || input[index] == b' ' {
            output.extend_from_slice(&capitalize_ascii(&input[segment_start..index]));
            if index < input.len() {
                output.push(b' ');
            }
            segment_start = index + 1;
        }
    }

    output
}
