use std::process;

use super::case;

pub fn pluralize(input: &[u8]) -> Vec<u8> {
    let mut output = input.to_vec();
    output.push(b's');
    output
}

pub fn singularize(input: &[u8]) -> Vec<u8> {
    if input.last() == Some(&b's') {
        input[..input.len() - 1].to_vec()
    } else {
        input.to_vec()
    }
}

pub fn camelize(input: &[u8], uppercase_first_letter: bool) -> Vec<u8> {
    let mut output = Vec::with_capacity(input.len());
    let mut uppercase_next = false;

    for &byte in input {
        if byte == b'_' {
            uppercase_next = true;
            continue;
        }

        if uppercase_next {
            output.push(byte.to_ascii_uppercase());
            uppercase_next = false;
        } else {
            output.push(byte);
        }
    }

    if uppercase_first_letter {
        if let Some(first) = output.first_mut() {
            *first = first.to_ascii_uppercase();
        }
    }

    output
}

pub fn underscore(input: &[u8]) -> Vec<u8> {
    let mut output = Vec::with_capacity(input.len());

    for (index, &byte) in input.iter().enumerate() {
        if byte.is_ascii_uppercase() {
            if index > 0 {
                output.push(b'_');
            }
            output.push(byte.to_ascii_lowercase());
        } else {
            output.push(byte);
        }
    }

    output
}

pub fn classify(input: &[u8]) -> Vec<u8> {
    let singular = singularize(input);
    camelize(&singular, true)
}

pub fn tableize(input: &[u8]) -> Vec<u8> {
    let underscored = underscore(input);
    pluralize(&underscored)
}

pub fn humanize(input: &[u8]) -> Vec<u8> {
    let replaced: Vec<u8> = input
        .iter()
        .map(|&byte| if byte == b'_' { b' ' } else { byte })
        .collect();
    case::uppercase_first_ascii(&replaced)
}

pub fn titleize(input: &[u8]) -> Vec<u8> {
    case::titleize_ascii_words(input)
}

pub fn dasherize(input: &[u8]) -> Vec<u8> {
    input.iter()
        .map(|&byte| if byte == b'_' { b'-' } else { byte })
        .collect()
}

pub fn parameterize(input: &[u8]) -> Vec<u8> {
    let filtered: Vec<u8> = input
        .iter()
        .filter_map(|&byte| {
            if byte.is_ascii_alphanumeric() {
                Some(byte.to_ascii_lowercase())
            } else if byte == b' ' {
                Some(b'-')
            } else {
                None
            }
        })
        .collect();

    let start = filtered
        .iter()
        .position(|&byte| byte != b'-')
        .unwrap_or(filtered.len());
    let end = filtered
        .iter()
        .rposition(|&byte| byte != b'-')
        .map(|index| index + 1)
        .unwrap_or(start);

    filtered[start..end].to_vec()
}

pub fn truncate(input: &[u8], length: usize) -> Vec<u8> {
    if input.len() > length {
        let keep = length.saturating_sub(3);
        let mut output = input[..keep].to_vec();
        output.extend_from_slice(b"...");
        output
    } else {
        input.to_vec()
    }
}

pub fn demodulize_buggy(input: &[u8]) -> Vec<u8> {
    if let Some(index) = input.iter().rposition(|&byte| byte == b':') {
        let start = index + 2;
        if start > input.len() {
            process::abort();
        }
        input[start..].to_vec()
    } else {
        input.to_vec()
    }
}

pub fn is_plural(input: &[u8]) -> bool {
    input.last() == Some(&b's')
}

pub fn is_singular(input: &[u8]) -> bool {
    !is_plural(input)
}

pub fn ordinalize(value: i32) -> Vec<u8> {
    let suffix = match value % 100 {
        11 | 12 | 13 => "th",
        _ => match value % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        },
    };

    format!("{value}{suffix}").into_bytes()
}
